+    ).toBe(true);
+  });
+
+  it("defined title → undefined title triggers reset", () => {
+    expect(
+      shouldResetPage(
+        { ...base, title: "old query" },
+        { ...base, title: undefined },
+      ),
+    ).toBe(true);
+  });
+
+  it("empty string title → undefined title does NOT reset (both are empty)", () => {
